use std::fmt;
use std::cmp::Ordering;

// ---- A struct with common traits derived ----
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
struct Player {
    id: u32,
    name: String,
    level: u32,
    health: i32,
}

// ---- Manual implementation of Display ----
impl fmt::Display for Player {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{} (Lv. {}, HP: {})", self.name, self.level, self.health)
    }
}

// ---- Manual implementation of PartialOrd ----
impl PartialOrd for Player {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

// ---- Manual implementation of Ord ----
impl Ord for Player {
    fn cmp(&self, other: &Self) -> Ordering {
        // Sort by level descending, then by name ascending
        match other.level.cmp(&self.level) {
            Ordering::Equal => self.name.cmp(&other.name),
            other => other,
        }
    }
}

// ---- Manual implementation of Default ----
impl Default for Player {
    fn default() -> Self {
        Player {
            id: 0,
            name: String::from("Unknown"),
            level: 1,
            health: 100,
        }
    }
}

// ---- Manual implementation of Clone for a struct with references ----
struct Item<'a> {
    name: &'a str,
    value: i32,
}

impl<'a> Clone for Item<'a> {
    fn clone(&self) -> Self {
        Item {
            name: self.name,
            value: self.value,
        }
    }
}

// ---- Manual implementation of Debug ----
struct Color {
    red: u8,
    green: u8,
    blue: u8,
}

impl fmt::Debug for Color {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Color(r: {}, g: {}, b: {})", self.red, self.green, self.blue)
    }
}

// ---- From trait ----
struct Health(i32);

impl From<i32> for Health {
    fn from(value: i32) -> Self {
        Health(value)
    }
}

impl Into<i32> for Health {
    fn into(self) -> i32 {
        self.0
    }
}

// ---- Iterator trait ----
struct Counter {
    count: i32,
    max: i32,
}

impl Counter {
    fn new(max: i32) -> Self {
        Counter { count: 0, max }
    }
}

impl Iterator for Counter {
    type Item = i32;

    fn next(&mut self) -> Option<Self::Item> {
        if self.count < self.max {
            self.count += 1;
            Some(self.count)
        } else {
            None
        }
    }
}

fn main() {
    // ---- Derived traits ----
    let player1 = Player {
        id: 1,
        name: String::from("Hero"),
        level: 5,
        health: 100,
    };

    let player2 = Player {
        id: 2,
        name: String::from("Aragorn"),
        level: 8,
        health: 120,
    };

    let player3 = Player {
        id: 3,
        name: String::from("Hero"),
        level: 5,
        health: 80,
    };

    // ---- Debug ----
    println!("Debug: {:?}", player1);

    // ---- Display ----
    println!("Display: {}", player1);

    // ---- Clone ----
    let player4 = player1.clone();
    println!("Cloned: {}", player4);

    // ---- PartialEq ----
    println!("player1 == player3: {}", player1 == player3);
    println!("player1 == player2: {}", player1 == player2);

    // ---- Ord ----
    println!("player1 < player2: {}", player1 < player2);
    println!("player1 > player2: {}", player1 > player2);

    // ---- Default ----
    let default_player = Player::default();
    println!("Default: {}", default_player);

    // ---- From/Into ----
    let health: Health = Health::from(100);
    let value: i32 = health.into();
    println!("Health: {}, Value: {}", health.0, value);

    // ---- Iterator ----
    let counter = Counter::new(5);
    for value in counter {
        println!("Counter: {}", value);
    }
}

